// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public {
        c = new DnGmxBatchingManager();
    }
    function testFuzz_property(bool initialPaused) public {
        vm.assume(initialPaused == false || initialPaused == true);
        PausedGetter getter = new PausedGetter(address(c));

        bool isPaused = c.paused();
        assertEq(isPaused, false, "paused() should return false in default state");
    }
}

contract PausedGetter {
    DnGmxBatchingManager public target;
    constructor(address _target) {
        target = DnGmxBatchingManager(_target);
    }
}
